parameters.jsCode:
const briefData = $('Validate Brief').item.json;
const ctx = $('Hydrate Context').item.json || {};
const senderRows = $('Resolve Sender').item.json;
const senderProfile = (Array.isArray(senderRows) ? senderRows[0] : senderRows) || {};
const { brief, scenario, isPitch } = briefData;

function truncate(str, max) {
  if (!str) return '';
  return String(str).length > max ? String(str).slice(0, max) + '…' : String(str);
}

const recipient = brief.who.recipient;
const sender = brief.who.sender || {};
const senderName = sender.name || senderProfile.full_name || senderProfile.email || 'Un collaborateur Kredo';

if (isPitch) {
  const SYSTEM_PROMPT_SPOKEN_PITCH = `Tu es un coach commercial expert pour une ESN (Entreprise de Services du Numérique)
nommée Kredo Digital. Tu rédiges des scripts de pitch oral pour des appels de prospection
de 30 secondes environ (80 à 100 mots à l'oral). Ce texte sera LU À VOIX HAUTE par un
Business Manager au téléphone, jamais envoyé par écrit.

RÈGLES ABSOLUES :
1. Tu ne dois JAMAIS inventer de chiffres, de références clients ou de résultats
   qui ne figurent pas dans le CONTEXTE fourni.
2. Tu ne dois JAMAIS mentionner d'offre ou de service hors de l'OFFRE CATALOGUE fournie.
   Tu ne dois JAMAIS inventer un nom d'offre.
3. Tu ne dois JAMAIS engager un prix ferme. Si un TJM figure dans la GRILLE TARIFAIRE,
   formule-le comme un ordre de grandeur ("à partir de", "de l'ordre de", "selon profil"),
   jamais comme un prix contractuel.
4. Le texte doit pouvoir être dit à voix haute en environ 30 secondes (80-100 mots au total
   pour l'ensemble des 5 blocs).
5. Le bloc "ask" DOIT contenir une proposition concrète et mesurable (durée, format).

FORMAT DE SORTIE : réponds UNIQUEMENT en JSON valide, sans backticks, structure exacte :
{
  "kind": "spoken_pitch",
  "hook": "accroche 1-2 phrases",
  "problem_recognition": "preuve qu'on connaît leur contexte",
  "offer_link": "lien vers l'offre catalogue en langage client",
  "ask": "appel à l'action mesurable",
  "alt_close": "repli si refus (\"pas maintenant\")",
  "word_count": 0,
  "tone_notes": ["instruction de prononciation"],
  "source_refs": ["donnée du contexte utilisée"],
  "warnings": ["avertissement si contexte insuffisant"]
}`;

  const SYSTEM_PROMPT_MEETING_BRIEFING = `Tu es un coach commercial expert pour une ESN (Entreprise de Services du Numérique)
nommée Kredo Digital. Tu rédiges une fiche de préparation de rendez-vous commercial —
un briefing structuré que le Business Manager consulte avant d'entrer en réunion,
jamais un texte à lire tel quel.

RÈGLES ABSOLUES :
1. Tu ne dois JAMAIS inventer de chiffres, de références clients ou de résultats
   qui ne figurent pas dans le CONTEXTE fourni.
2. Tu ne dois JAMAIS mentionner d'offre hors de l'OFFRE CATALOGUE fournie. Les hypothèses
   de cross-sell doivent uniquement citer des practices listées dans OFFRES SUGGÉRÉES.
3. Tu ne dois JAMAIS engager un prix ferme — les chiffres de la GRILLE TARIFAIRE sont
   des ordres de grandeur, jamais des prix contractuels.
4. Chaque argument DOIT avoir une preuve (evidence) concrète ancrée dans le CONTEXTE,
   jamais une affirmation générique.
5. Exactement 3 arguments et 3 objections attendues, ni plus ni moins.

FORMAT DE SORTIE : réponds UNIQUEMENT en JSON valide, sans backticks, structure exacte :
{
  "kind": "meeting_briefing",
  "objective": "objectif du RDV en une phrase",
  "key_message": "proposition de valeur en une phrase",
  "arguments": [{ "title": "", "evidence": "", "source_ref": "" }],
  "expected_objections": [{ "objection": "", "response": "", "fallback": "" }],
  "cross_sell_hypotheses": ["practice ou offre à explorer, si pertinent"],
  "data_points_to_mention": ["chiffre à citer"],
  "close_options": ["sortie possible du RDV"],
  "do_not_say": ["sujet à éviter"],
  "source_refs": ["donnée du contexte utilisée"],
  "warnings": ["avertissement si contexte insuffisant"]
}`;

  const PITCH_SCENARIO_MISSIONS = {
    cold_call_pitch: `MISSION : rédige un script de pitch oral pour un appel de prospection à froid ou tiède.
L'accroche doit justifier pourquoi on appelle CE compte maintenant (signal, actualité, secteur).
Le ask doit être un premier pas léger (15-20 minutes), pas un engagement lourd.`,
    meeting_prep_discovery: `MISSION : rédige une fiche de préparation pour un premier rendez-vous de découverte.
Les arguments doivent partir des enjeux sectoriels ou des signaux du compte, pas du catalogue Kredo.
Les objections attendues doivent correspondre à un prospect qui ne connaît pas encore Kredo.`,
    meeting_prep_cross_sell: `MISSION : rédige une fiche de préparation pour un rendez-vous chez un client actif,
avec un objectif explicite de cross-sell vers une offre non encore consommée.
Le message clé DOIT s'appuyer sur la mission en cours et la satisfaction existante.
Les hypothèses de cross-sell DOIVENT correspondre aux practices listées dans OFFRES SUGGÉRÉES,
jamais une practice déjà livrée (voir PRACTICES DÉJÀ LIVRÉES).`,
  };

  const offer = ctx.offer;
  const sections = [];

  if (ctx.company) {
    sections.push(`-- Fiche compte --\n${ctx.company.name} - secteur : ${ctx.company.sector || 'non renseigné'} (${ctx.company.lifecycle_status}) - ${truncate(ctx.company.description || '', 400)}`);
  }
  if (offer) {
    sections.push(`-- OFFRE CATALOGUE (ancrage obligatoire) --\n${offer.name} (practice ${offer.practice})\n${offer.short_description}\nLivrables types : ${(offer.typical_deliverables || []).join(', ')}\nCas d'usage : ${(offer.use_cases || []).join(', ')}`);
  }
  if (ctx.pricingGrid && ctx.pricingGrid.length) {
    const lines = ctx.pricingGrid.slice(0, 4).map(g => `${g.profile_name} (${g.seniority_level}) : ${g.tjm_min}-${g.tjm_max}${g.currency} (reco ${g.tjm_recommended})`);
    sections.push(`-- GRILLE TARIFAIRE (ordre de grandeur, jamais un prix ferme) --\n${lines.join('\n')}`);
  }
  if (ctx.deliveredPractices && ctx.deliveredPractices.length) {
    sections.push(`-- PRACTICES DÉJÀ LIVRÉES chez ce compte --\n${ctx.deliveredPractices.join(', ')}`);
  }
  if (ctx.suggestedPractices && ctx.suggestedPractices.length) {
    sections.push(`-- OFFRES SUGGÉRÉES (cross-sell possible) --\n${ctx.suggestedPractices.map(p => p.name).join(', ')}`);
  }
  if (ctx.anchorOpportunity) {
    sections.push(`-- Opportunité visée --\n${ctx.anchorOpportunity.need_summary || ctx.anchorOpportunity.title} - étape ${ctx.anchorOpportunity.stage}`);
  }
  if (ctx.anchorMission) {
    sections.push(`-- Mission en cours (ancrage cross-sell) --\n${ctx.anchorMission.title} - ${ctx.anchorMission.role_title || ''} depuis le ${ctx.anchorMission.start_date}`);
  } else if (ctx.activeMissions && ctx.activeMissions.length) {
    const lines = ctx.activeMissions.slice(0, 3).map(m => `${m.title} - ${m.role_title || ''} depuis le ${m.start_date}`);
    sections.push(`-- Missions en cours --\n${lines.join('\n')}`);
  }
  if (ctx.recentInteractions && ctx.recentInteractions.length) {
    const lines = ctx.recentInteractions.slice(0, 3).map(i => `${(i.occurred_at || '').slice(0,10)} - ${i.type} - ${truncate(i.summary || '', 150)}`);
    sections.push(`-- Historique commercial --\n${lines.join('\n')}`);
  }
  if (ctx.sectorIntelligence) {
    const fit = ctx.sectorIntelligence.practices_fit ? JSON.stringify(ctx.sectorIntelligence.practices_fit) : '';
    sections.push(`-- Intelligence sectorielle --\n${ctx.sectorIntelligence.name} - fit practices : ${fit}`);
  }
  if (ctx.sectorNews && ctx.sectorNews.length) {
    const lines = ctx.sectorNews.map(n => `${(n.published_at || '').slice(0,10)} - ${n.title}`);
    sections.push(`-- Signal/Actualité sectorielle --\n${lines.join('\n')}`);
  }
  if (ctx.previousPitches && ctx.previousPitches.length) {
    sections.push(`-- Pitchs précédents pour ce compte (ne pas répéter le même angle) --\n${ctx.previousPitches.length} pitch(s) déjà généré(s)`);
  }
  if (ctx.legacyPitches && ctx.legacyPitches.length) {
    sections.push(`-- Exemples de ton historiques (à imiter comme STYLE uniquement, jamais comme faits) --\n${truncate(JSON.stringify(ctx.legacyPitches), 500)}`);
  }
  if (ctx.scores) {
    sections.push(`-- Scores déterministes (calculés par Kredo, ne jamais recalculer) --\nConviction ${ctx.scores.conviction}/5 - Investissement ${ctx.scores.investment}/5`);
  }

  const contextBlock = sections.join('\n\n');
  const isSpoken = brief.what.channel === 'spoken_pitch_30s';
  const systemPrompt = isSpoken ? SYSTEM_PROMPT_SPOKEN_PITCH : SYSTEM_PROMPT_MEETING_BRIEFING;

  const userPrompt = `${PITCH_SCENARIO_MISSIONS[scenario] || ''}

ÉMETTEUR :
${senderName}${sender.practice ? ' - practice ' + sender.practice : ''}

DESTINATAIRE :
${recipient.displayName || 'Non renseigné'} - ${recipient.persona || ''} chez ${recipient.companyName || (ctx.company && ctx.company.name) || ''}
Relation : ${recipient.relation || ''}

TON :
${brief.how.tone}

CONTEXTE DISPONIBLE :
${contextBlock || '(contexte limité)'}

INSTRUCTIONS IMPÉRATIVES DE L'UTILISATEUR :
${(brief.context && brief.context.mustInclude) || '(aucune)'}`;

  return [{
    json: {
      ...briefData,
      resolvedContext: ctx,
      systemPrompt,
      userPrompt,
    }
  }];
}

const SYSTEM_PROMPT = `Tu es un rédacteur commercial expert pour une ESN (Entreprise de Services du Numérique)
nommée Kredo Digital. Tu rédiges des messages commerciaux B2B de haute qualité.

RÈGLES ABSOLUES :
1. Tu ne dois JAMAIS inventer de chiffres, de références clients, de résultats
   quantifiés ou de noms de projets qui ne figurent pas dans le CONTEXTE fourni.
2. Tu ne dois JAMAIS mentionner d'informations listées dans la section EXCLUSIONS.
3. Tu dois respecter STRICTEMENT le niveau de langue demandé (vouvoiement/tutoiement).
4. Tu dois respecter la longueur demandée (±20% tolérance).
5. Tu ne dois JAMAIS utiliser de superlatifs creux ("leader", "unique", "révolutionnaire").
6. Tu dois produire un message naturel, pas un template générique.
7. Si le contexte est insuffisant pour un argument spécifique, reste général plutôt
   que d'inventer.

FORMAT DE SORTIE :
Tu dois répondre UNIQUEMENT en JSON valide, sans backticks, sans commentaires.
Structure obligatoire :
{
  "subjects": ["objet 1", "objet 2", "objet 3"],
  "body": "le corps complet du message",
  "key_points": ["point clé 1", "point clé 2"],
  "source_refs": ["description de chaque donnée du CONTEXTE utilisée"],
  "warnings": ["avertissement si un fait semble incertain ou si le contexte manque"]
}

Pour les invitations LinkedIn (max 300 caractères), le champ "subjects" est vide
et "body" contient uniquement le message court.`;

const SCENARIO_MISSIONS = {
  signal_outreach: `MISSION : Rédige un premier mail de prise de contact basé sur l'actualité ou le signal fourni.
L'accroche DOIT mentionner le signal de manière naturelle (félicitation, référence à l'actualité).
Le message DOIT créer un pont entre le signal et une expertise Kredo pertinente.
Ne sois pas commercial trop vite — la première interaction doit créer de la valeur.`,
  follow_up_no_reply: `MISSION : Rédige une relance après un premier message resté sans réponse.
Le message doit être plus court que le précédent.
Ne répète pas le contenu du premier message — apporte un nouvel angle ou une nouvelle valeur.
Évite les formulations passives-agressives ("je me permets de revenir", "au cas où").
Si un pitch précédent existe dans le contexte, ne reprends pas les mêmes arguments.`,
  post_meeting: `MISSION : Rédige un mail de suivi après un rendez-vous.
Le message DOIT :
- Remercier brièvement
- Résumer les points clés discutés (si disponibles dans les interactions)
- Confirmer les prochaines étapes
- Proposer une action concrète (date, livrable, mise en relation)
Ton : professionnel et engagé, pas servile.`,
  profile_submission: `MISSION : Rédige un mail présentant un profil de consultant ou candidat.
Le message DOIT :
- Contextualiser pourquoi ce profil correspond au besoin
- Mettre en avant 2-3 points forts du profil (si disponibles)
- Proposer une mise en relation ou un entretien
Ne pas survendre — le CV parle de lui-même.`,
  cross_sell: `MISSION : Rédige un mail proposant un service complémentaire à un client chez qui
une mission est déjà en cours.
L'accroche DOIT faire référence à la mission existante et à la satisfaction.
Le message doit montrer que la proposition est naturelle et cohérente, pas opportuniste.`,
  reactivation: `MISSION : Rédige un mail de reprise de contact avec un ancien client ou contact inactif.
Le message DOIT :
- Rappeler le contexte de la relation passée (si disponible)
- Apporter un élément nouveau (actualité, offre, événement)
- Ne pas être culpabilisant sur le silence
Ton : chaleureux et léger, pas commercial d'emblée.`,
  proposal_follow_up: `MISSION : Rédige une relance après l'envoi d'une proposition commerciale.
Le message DOIT :
- Ne pas simplement "prendre des nouvelles"
- Apporter un élément de valeur complémentaire
- Faciliter la décision (réponse aux objections courantes, flexibilité)
Évite la pression — l'objectif est de faciliter, pas de forcer.`,
  offer_introduction: `MISSION : Rédige un mail présentant une offre ou une practice Kredo.
Le message DOIT :
- Partir du besoin client (pas de la solution Kredo)
- Montrer la valeur métier avant la capacité technique
- Être spécifique au secteur du destinataire
Évite le catalogue — un seul angle, une seule offre, un seul bénéfice principal.`,
};

const LENGTH_RANGES = {
  ultra_short: '40-80 mots',
  concise: '80-140 mots',
  standard: '140-220 mots',
  detailed: '220-400 mots',
};

const sections = [];

if (ctx.company) {
  sections.push(`-- Fiche compte --\n${ctx.company.name} · secteur : ${ctx.company.sector || 'non renseigné'} · ${truncate(ctx.company.description || '', 400)}`);
}
if (ctx.recentInteractions && ctx.recentInteractions.length) {
  const lines = ctx.recentInteractions.slice(0, 3).map(i => `${(i.occurred_at || '').slice(0,10)} · ${i.type} · ${truncate(i.summary || '', 150)}`);
  sections.push(`-- Historique commercial --\n${lines.join('\n')}`);
}
if (ctx.activeOpportunities && ctx.activeOpportunities.length) {
  const lines = ctx.activeOpportunities.slice(0, 3).map(o => `${o.need_summary || o.opportunity_type || 'opportunité'} · étape ${o.stage} · ~${o.estimated_gain || '?'}€`);
  sections.push(`-- Opportunités actives --\n${lines.join('\n')}`);
}
if (ctx.activeMissions && ctx.activeMissions.length) {
  const lines = ctx.activeMissions.slice(0, 3).map(m => `${m.title} · ${m.role_title || ''} · depuis le ${m.start_date}`);
  sections.push(`-- Missions en cours --\n${lines.join('\n')}`);
}
if (ctx.sectorNews && ctx.sectorNews.length) {
  const lines = ctx.sectorNews.map(n => `${(n.published_at || '').slice(0,10)} · ${n.title} · ${truncate(n.summary || '', 150)}`);
  sections.push(`-- Signal/Actualité sectorielle --\n${lines.join('\n')}`);
}
if (ctx.sectorIntelligence) {
  sections.push(`-- Intelligence sectorielle --\n${ctx.sectorIntelligence.name} · ${truncate(JSON.stringify(ctx.sectorIntelligence.playbook || {}), 300)}`);
}
if (ctx.previousCommunications && ctx.previousCommunications.length) {
  const lines = ctx.previousCommunications.map(p => truncate(JSON.stringify((p.content_json && (p.content_json.key_points || p.content_json.body)) || ''), 150));
  sections.push(`-- Communications précédentes --\n${lines.join('\n')}`);
}

let contextBlock = sections.join('\n\n');
const MAX_CONTEXT_CHARS = 8000;
if (contextBlock.length > MAX_CONTEXT_CHARS) {
  const priorityOrder = ['-- Communications précédentes --', '-- Intelligence sectorielle --', '-- Historique commercial --'];
  for (const marker of priorityOrder) {
    if (contextBlock.length <= MAX_CONTEXT_CHARS) break;
    const idx = sections.findIndex(s => s.startsWith(marker));
    if (idx >= 0) sections.splice(idx, 1);
    contextBlock = sections.join('\n\n');
  }
  contextBlock = truncate(contextBlock, MAX_CONTEXT_CHARS);
}

const userPrompt = `${SCENARIO_MISSIONS[scenario] || ''}

ÉMETTEUR :
Nom : ${senderName}
Rôle : ${sender.role || senderProfile.role || ''}
${sender.practice ? `Practice : ${sender.practice}` : ''}
Entreprise : Kredo Digital — ESN premium spécialisée en Data/IA, Cloud, Product Management et Cybersécurité

DESTINATAIRE :
Nom : ${recipient.displayName || 'Non renseigné'}
Fonction : ${recipient.persona || ''}
Entreprise : ${recipient.companyName || (ctx.company && ctx.company.name) || ''}
Type de relation : ${recipient.relation || ''}

OBJECTIF DU MESSAGE :
${brief.who.objective || ''}

STYLE :
Canal : ${brief.what.channel}
Ton : ${brief.how.tone}
Langue : ${brief.how.language === 'en' ? 'Anglais' : 'Français'}
Formalité : ${brief.how.formality}
Longueur : ${LENGTH_RANGES[brief.what.length] || LENGTH_RANGES.standard}

CONTEXTE DISPONIBLE :
${contextBlock || '(contexte limité — nouveau prospect ou compte peu renseigné)'}

INSTRUCTIONS IMPÉRATIVES DE L'UTILISATEUR :
${(brief.context && brief.context.mustInclude) || '(aucune)'}

EXCLUSIONS :
${(brief.context && brief.context.mustExclude) || '(aucune)'}`;

return [{
  json: {
    ...briefData,
    resolvedContext: ctx,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt: userPrompt,
  }
}];

parameters.jsonBody:
={{ {
  model: "claude-sonnet-5",
  max_tokens: 4000,
  thinking: { type: "disabled" },
  system: $json.systemPrompt,
  messages: [ { role: "user", content: $json.userPrompt } ]
} }}

parameters.jsCode:
const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = upstream.isPitch
    ? { kind: null, warnings: ['output_not_json'] }
    : { subjects: [], body: content, key_points: [], source_refs: [], warnings: ['output_not_json'] };
}

if (upstream.isPitch) {
  const isSpoken = upstream.brief.what.channel === 'spoken_pitch_30s';
  const expectedKind = isSpoken ? 'spoken_pitch' : 'meeting_briefing';
  if (parsed.kind !== expectedKind) {
    throw new Error(`Sortie pitch invalide : kind attendu "${expectedKind}", reçu "${parsed.kind}"`);
  }
  if (isSpoken) {
    if (!parsed.hook || !parsed.ask) {
      throw new Error('Pitch oral incomplet : hook et ask sont requis');
    }
  } else {
    if (!parsed.objective || !parsed.key_message || !Array.isArray(parsed.arguments) || parsed.arguments.length === 0) {
      throw new Error('Fiche de préparation incomplète : objective, key_message et arguments sont requis');
    }
  }
} else {
  if (!parsed.body || parsed.body.length < 20) {
    throw new Error('Le corps généré est vide ou trop court');
  }
}

return [{
  json: {
    ...upstream,
    generatedOutput: parsed,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

const data = $input.first().json;
const brief = data.brief;
const output = data.generatedOutput;
const qaFlags = [];

if (data.isPitch) {
  const isSpoken = brief.what.channel === 'spoken_pitch_30s';
  const fullText = isSpoken
    ? [output.hook, output.problem_recognition, output.offer_link, output.ask, output.alt_close].filter(Boolean).join(' ')
    : [output.objective, output.key_message, ...(output.arguments || []).map(a => `${a.title} ${a.evidence}`), ...(output.expected_objections || []).map(o => `${o.objection} ${o.response}`), ...(output.data_points_to_mention || []), ...(output.close_options || [])].filter(Boolean).join(' ');

  const offerName = (data.resolvedContext && data.resolvedContext.offer && data.resolvedContext.offer.name) || null;
  const offerMentioned = offerName ? fullText.toLowerCase().includes(offerName.toLowerCase().split(',')[0].trim()) : false;
  const hasOfferRef = !!offerName && (offerMentioned || !!output.offer_link);
  qaFlags.push({ check: 'has_offer_ref', passed: hasOfferRef, detail: offerName ? `Offre attendue : ${offerName}` : 'Aucune offre en contexte — brief.context.offerRef manquant en amont' });

  if (isSpoken) {
    const wordCount = fullText.split(/\s+/).filter(Boolean).length;
    const inTarget = wordCount >= 60 && wordCount <= 130;
    qaFlags.push({ check: 'word_count_in_target', passed: inTarget, detail: `${wordCount} mots (cible 80-100)` });
    qaFlags.push({ check: 'has_call_to_action', passed: !!(output.ask && output.ask.trim().length > 0), detail: output.ask ? 'ask présent' : 'ask manquant' });
  } else {
    const allHaveEvidence = Array.isArray(output.arguments) && output.arguments.length > 0 && output.arguments.every(a => a.evidence && a.evidence.trim().length > 0);
    qaFlags.push({ check: 'arguments_have_evidence', passed: allHaveEvidence, detail: allHaveEvidence ? 'ok' : 'un argument sans evidence' });
    qaFlags.push({ check: 'has_call_to_action', passed: Array.isArray(output.close_options) && output.close_options.length > 0, detail: 'close_options' });
  }

  const normalizeAccents = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const priceCommitmentPattern = /\d{2,4}\s?€/;
  const softeners = /a partir de|environ|selon profil|suivant profil|entre|de l'ordre de|ordre de grandeur/i;
  const normalizedText = normalizeAccents(fullText);
  const hasPriceNumbers = priceCommitmentPattern.test(fullText);
  const hasSoftener = softeners.test(normalizedText);
  qaFlags.push({
    check: 'no_price_commitment',
    passed: !hasPriceNumbers || hasSoftener,
    detail: hasPriceNumbers && !hasSoftener ? "Montant cité sans formulation d'ordre de grandeur" : 'ok',
  });

  return [{ json: { ...data, qaFlags } }];
}

const body = output.body;

const wordCount = body.split(/\s+/).filter(Boolean).length;
const limits = {
  ultra_short: [30, 100],
  concise: [60, 170],
  standard: [120, 270],
  detailed: [180, 500],
};
const range = limits[brief.what.length] || [60, 300];
const min = range[0], max = range[1];
if (wordCount < min || wordCount > max) {
  qaFlags.push({ check: 'length', passed: false, detail: `${wordCount} mots (attendu ${min}-${max})` });
} else {
  qaFlags.push({ check: 'length', passed: true, detail: `${wordCount} mots` });
}

if (brief.how.formality === 'vous' && /\btu\b|\bt'|\bton\b|\bta\b|\btes\b/i.test(body)) {
  qaFlags.push({ check: 'formality', passed: false, detail: 'Tutoiement détecté malgré vouvoiement demandé' });
}

if (brief.context && brief.context.mustExclude) {
  const excluded = brief.context.mustExclude.toLowerCase().split(/[,;\n]/).map(s => s.trim()).filter(Boolean);
  for (const term of excluded) {
    if (term && body.toLowerCase().includes(term)) {
      qaFlags.push({ check: 'exclusion', passed: false, detail: `Terme exclu présent : "${term}"` });
    }
  }
}

if (brief.who.recipient.displayName) {
  const lastName = brief.who.recipient.displayName.split(' ').pop();
  if (lastName && !body.includes(lastName)) {
    qaFlags.push({ check: 'recipient_name', passed: false, detail: 'Nom du destinataire absent du message' });
  }
}

const ctaPatterns = /rendez-vous|rencontrer|échanger|appel|disponible|créneau|discuter|meeting|call/i;
if (!ctaPatterns.test(body)) {
  qaFlags.push({ check: 'cta_present', passed: false, detail: "Aucun appel à l'action détecté" });
}

return [{
  json: {
    ...data,
    qaFlags,
  }
}];

const data = $input.first().json;
const output = data.generatedOutput;

const resultType = data.isPitch ? 'commercial_pitch' : 'communication';

// Titre concis dérivé du brief (type + objectif), jamais de la phrase générée —
// un pitch affiché avec sa propre accroche en guise de titre est illisible dans
// les listes/dialogs (bug remonté après premier test réel).
const PITCH_CHANNEL_LABELS = {
  spoken_pitch_30s: 'Pitch 30 s',
  meeting_briefing: 'Fiche de préparation RDV',
};
const PITCH_OBJECTIVE_LABELS = {
  get_meeting: 'Obtenir un rendez-vous',
  get_reply: 'Obtenir une réponse',
  present_offer: 'Présenter une offre',
  accelerate_decision: 'Accélérer une décision',
};

function buildPitchTitle(brief) {
  const channelLabel = PITCH_CHANNEL_LABELS[brief.what.channel] || brief.what.channel;
  const objective = brief.who && brief.who.objective;
  const objectiveLabel = objective ? (PITCH_OBJECTIVE_LABELS[objective] || objective) : null;
  return objectiveLabel ? `${channelLabel} — ${objectiveLabel}` : channelLabel;
}

const title = data.isPitch
  ? buildPitchTitle(data.brief)
  : ((output.subjects && output.subjects[0]) || null);

const callbackBody = {
  runId: data.runId,
  phase: 5,
  resultType: resultType,
  status: 'succeeded',
  contentJson: output,
  title: title,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.resolvedContext || null,
  sourceRefs: (output.source_refs || []).map(s => ({ entityType: 'context', label: s })),
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

